 static ObjectValue replace(ObjectValue o,String name,CanonicalValue value){return new ObjectValue(o.entries().stream().map(e->e.key().equals(name)?field(name,value):e).toList());}
 static MinutesRecordedLookup.Reconstruction check(ObjectValue manifest,ObjectValue envelope,TaskSpec spec,String task,Map<String,Object> input){String hash=new CanonicalValueCodec().sha256(ContractValues.envelope("ama.minutes-model-request.v1","MODEL_REQUEST",envelope),B,()->false);var row=new HashMap<String,Object>();row.put("request_hash",hash);row.put("logical_hash",hash);row.put("business_key","minutes:"+spec.input().id());row.put("operation_kind","MINUTES_GENERATE");return MinutesRecordedLookup.reconstruct(new String(CanonicalJson.encode(manifest,65536,()->false),java.nio.charset.StandardCharsets.UTF_8),spec,task,input,row,B);}
